-- The Dashboard AI webhook is shared by every branch: reuse Bangalore's.
insert into public.branch_settings (branch_id, key, value)
select '65af2063-7d87-49b6-ac95-67572b964384'::uuid, key, value from public.branch_settings
 where key = 'ai_webhook_url' and branch_id = (select id from public.branches where slug = 'bangalore')
on conflict (branch_id, key) do nothing;

-- Rewards programme, only if Kadri has none yet.
insert into public.loyalty_programs
select * from jsonb_populate_recordset(null::public.loyalty_programs, $fkjson$[{"id":"ce781cbe-a699-4c75-9dca-9cdc6c91890c","branch_id":"65af2063-7d87-49b6-ac95-67572b964384","name":"Fried King Rewards","currency_name":"points","type":"points","earn_rate_per_rupee":0.1,"earn_rate_per_visit":1,"redemption_paise_per_point":10,"min_spend_to_earn_paise":10000,"max_redeem_pct_per_order":100,"max_redeem_paise_per_day":null,"points_expiry_days":30,"tiers":[],"is_active":true,"created_at":"2026-11-23T07:00:39.601927+00:00","updated_at":"2026-11-23T07:00:39.601927+00:00"}]$fkjson$::jsonb) l
where not exists (select 1 from public.loyalty_programs p where p.branch_id = '65af2063-7d87-49b6-ac95-67572b964384');

-- Check: settings should now be 26 or 27 (27 once the OTP webhook file has also been run).
select b.slug,
  (select count(*) from public.branch_settings s where s.branch_id = b.id) as settings,
  (select count(*) from public.loyalty_programs p where p.branch_id = b.id) as rewards_programmes,
  (select string_agg(key, ', ' order by key) from public.branch_settings s where s.branch_id = b.id and key in ('whatsapp_number','menu_url','otp_template','otp_webhook_url','ai_webhook_url')) as key_settings
from public.branches b where b.slug = 'kadri';
